import{D as e,E as t,F as n,L as r,O as i,P as a,T as o,k as s,t as c}from"./app-Bm4k7Zkh.js";var l=JSON.parse(`{"path":"/interview/7_db.html","title":"数据库面试题解答","lang":"zh-CN","frontmatter":{"description":"事务、索引、锁、InnoDB、SQL 优化、主从、PostgreSQL、分库分表与迁移扩容、NoSQL、连接池与 CDC"},"git":{"createdTime":1736957148000,"updatedTime":1791535206000,"contributors":[{"name":"Clarence","username":"Clarence","email":"1154937362@qq.com","commits":4,"url":"https://github.com/Clarence"},{"name":"hanchen","username":"hanchen","email":"1154937362@qq.com","commits":7,"url":"https://github.com/hanchen"},{"name":"hello0709","username":"hello0709","email":"1154937362@qq.com","commits":9,"url":"https://github.com/hello0709"},{"name":"Claude Opus 5.5","username":"","email":"noreply@anthropic.com","commits":7}]},"readingTime":{"minutes":37.84,"words":11353},"filePathRelative":"interview/7_db.md"}`),u={name:`7_db.md`};function d(c,l,u,d,f,p){let m=n(`RouteLink`);return a(),t(`div`,null,[l[130]||=o(`h1`,{id:`数据库面试题解答`,tabindex:`-1`},[o(`a`,{class:`header-anchor`,href:`#数据库面试题解答`},[o(`span`,null,`数据库面试题解答`)])],-1),o(`blockquote`,null,[o(`p`,null,[l[5]||=i(`题目清单见 `,-1),s(m,{to:`/database/99_interview.html`},{default:r(()=>[...l[0]||=[i(`数据库面试题`,-1)]]),_:1}),l[6]||=i(`，细节见 `,-1),s(m,{to:`/database/0_overview.html`},{default:r(()=>[...l[1]||=[i(`数据库总览`,-1)]]),_:1}),l[7]||=i(`；缓存一致性、分布式事务、系统级分库分表见 `,-1),s(m,{to:`/interview/8_cache.html`},{default:r(()=>[...l[2]||=[i(`缓存面试题解答`,-1)]]),_:1}),l[8]||=i(`、`,-1),s(m,{to:`/interview/10_distributed.html`},{default:r(()=>[...l[3]||=[i(`分布式面试题解答`,-1)]]),_:1}),l[9]||=i(`、`,-1),s(m,{to:`/interview/13_high_con.html`},{default:r(()=>[...l[4]||=[i(`高并发面试题解答`,-1)]]),_:1}),l[10]||=i(`。`,-1)]),l[11]||=o(`p`,null,`版本基线：MySQL 8.4 LTS、PostgreSQL 18，其他组件取当前主流版本，差异处单独说明。`,-1)]),l[131]||=e(`<h2 id="一、事务与隔离级别" tabindex="-1"><a class="header-anchor" href="#一、事务与隔离级别"><span>一、事务与隔离级别</span></a></h2><h3 id="q1-mysql-有哪四种隔离级别-各自能解决什么问题-默认是哪一种" tabindex="-1"><a class="header-anchor" href="#q1-mysql-有哪四种隔离级别-各自能解决什么问题-默认是哪一种"><span>Q1：MySQL 有哪四种隔离级别？各自能解决什么问题？默认是哪一种？</span></a></h3><p><strong>一句话</strong>：从低到高是读未提交、读已提交（RC）、可重复读（RR）、串行化，级别越高防住的并发问题越多、性能越差。InnoDB 默认 RR，Oracle、PostgreSQL、SQL Server 默认 RC。</p><table><thead><tr><th>隔离级别</th><th style="text-align:center;">脏读</th><th style="text-align:center;">不可重复读</th><th style="text-align:center;">幻读</th></tr></thead><tbody><tr><td>READ UNCOMMITTED</td><td style="text-align:center;">可能</td><td style="text-align:center;">可能</td><td style="text-align:center;">可能</td></tr><tr><td>READ COMMITTED</td><td style="text-align:center;">避免</td><td style="text-align:center;">可能</td><td style="text-align:center;">可能</td></tr><tr><td>REPEATABLE READ（默认）</td><td style="text-align:center;">避免</td><td style="text-align:center;">避免</td><td style="text-align:center;">基本避免（见 Q3）</td></tr><tr><td>SERIALIZABLE</td><td style="text-align:center;">避免</td><td style="text-align:center;">避免</td><td style="text-align:center;">避免</td></tr></tbody></table><ul><li>很多团队把 MySQL 改成 RC：锁更少、死锁更少，代价是同一事务里两次读可能不一样</li><li>查看当前级别：<code>SELECT @@transaction_isolation;</code></li></ul>`,5),o(`p`,null,[l[13]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/5_topic_transaction.html#_2%E3%80%81%E5%9B%9B%E7%A7%8D%E9%9A%94%E7%A6%BB%E7%BA%A7%E5%88%AB`},{default:r(()=>[...l[12]||=[i(`MySQL 事务与锁`,-1)]]),_:1})]),l[132]||=e(`<h3 id="q2-脏读、不可重复读、幻读的区别" tabindex="-1"><a class="header-anchor" href="#q2-脏读、不可重复读、幻读的区别"><span>Q2：脏读、不可重复读、幻读的区别？</span></a></h3><p><strong>一句话</strong>：都是一个事务里读到了别的事务造成的变化。脏读是读到别人还没提交的数据；不可重复读是同一行读两次值变了；幻读是同一个条件查两次，多出了新插入的行。</p><ul><li>脏读：B 改了余额还没提交，A 就读到了，B 随后回滚，A 读到的是「不存在」的数据</li><li>不可重复读：A 两次读 id=1，中间 B 修改并提交了这一行</li><li>幻读：A 两次查 <code>age &gt; 18</code>，中间 B 插入了一个 20 岁的用户</li><li>防不可重复读只要保护「读过的行」；防幻读要保护「还不存在的行」，所以要锁住行之间的空隙（间隙锁）</li></ul><p><strong>常见坑</strong>：两个事务同时改同一行导致的「丢失更新」不属于这三类，要靠加锁或乐观锁版本号解决。</p>`,4),o(`p`,null,[l[15]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/5_topic_transaction.html#_1%E3%80%81%E4%B8%89%E7%A7%8D%E5%B9%B6%E5%8F%91%E8%AF%BB%E9%97%AE%E9%A2%98`},{default:r(()=>[...l[14]||=[i(`MySQL 事务与锁`,-1)]]),_:1})]),l[133]||=e(`<h3 id="q3-快照读和当前读有什么区别-rr-能在多大程度上避免幻读" tabindex="-1"><a class="header-anchor" href="#q3-快照读和当前读有什么区别-rr-能在多大程度上避免幻读"><span>Q3：快照读和当前读有什么区别？RR 能在多大程度上避免幻读？</span></a></h3><p><strong>一句话</strong>：普通 SELECT 是快照读，读的是事务开始时的「照片」，不加锁；<code>FOR UPDATE</code>、UPDATE、DELETE、INSERT 是当前读，读最新数据并加锁。RR 下只做快照读或只做当前读都不会幻读，两者混用就可能看到别人新插入的行。</p><ul><li>快照读防幻读：整个事务都用同一张「照片」</li><li>当前读防幻读：靠锁住范围（Next-Key Lock，即锁住记录和记录前的空隙），别人插不进来</li><li>混用的例子：先 SELECT 查到 0 行，别人插入并提交，再 UPDATE 却更新到了这行，之后 SELECT 就能看到它</li><li>RC 下当前读不锁空隙，幻读照常出现</li></ul><p><strong>常见坑</strong>：「先查再改」的业务第一步就用 <code>SELECT ... FOR UPDATE</code>，或直接执行带条件的 UPDATE 并检查影响行数。</p>`,4),o(`p`,null,[l[17]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/5_topic_transaction.html#_3%E3%80%81%E5%BF%AB%E7%85%A7%E8%AF%BB%E4%B8%8E%E5%BD%93%E5%89%8D%E8%AF%BB`},{default:r(()=>[...l[16]||=[i(`MySQL 事务与锁`,-1)]]),_:1})]),l[134]||=e(`<h3 id="q4-mvcc-的原理是什么-undo-log-和-read-view-如何配合-rc-与-rr-有何不同" tabindex="-1"><a class="header-anchor" href="#q4-mvcc-的原理是什么-undo-log-和-read-view-如何配合-rc-与-rr-有何不同"><span>Q4：MVCC 的原理是什么？undo log 和 Read View 如何配合？RC 与 RR 有何不同？</span></a></h3><p><strong>一句话</strong>：MVCC 就是一行数据保留多个历史版本，读的时候挑一个「自己该看到的」版本，这样读不用加锁。</p><ul><li>每行藏着两个字段：最后修改它的事务 ID、指向上一个版本的指针；旧版本存在 undo log 里，串成一条版本链</li><li>Read View 是一份「快照名单」：记录创建时哪些事务还没提交</li><li>读的时候沿版本链往回找：自己改的、或创建名单前已提交的版本可见，还没提交的不可见</li><li>RC 每次 SELECT 都新建 Read View，所以能读到别人刚提交的；RR 只在第一次 SELECT 时建一次，之后一直复用</li></ul><p><strong>常见坑</strong>：长事务一直拿着旧的 Read View，旧版本清理不掉，undo 越积越多；用 <code>information_schema.innodb_trx</code> 找出长事务。</p>`,4),o(`p`,null,[l[19]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/5_topic_transaction.html#%E4%B8%89%E3%80%81mvcc-%E5%A4%9A%E7%89%88%E6%9C%AC%E5%B9%B6%E5%8F%91%E6%8E%A7%E5%88%B6`},{default:r(()=>[...l[18]||=[i(`MySQL 事务与锁`,-1)]]),_:1})]),l[135]||=e(`<h3 id="q5-redo-log、undo-log、binlog-有什么区别-两阶段提交如何保证崩溃恢复一致" tabindex="-1"><a class="header-anchor" href="#q5-redo-log、undo-log、binlog-有什么区别-两阶段提交如何保证崩溃恢复一致"><span>Q5：redo log、undo log、binlog 有什么区别？两阶段提交如何保证崩溃恢复一致？</span></a></h3><p><strong>一句话</strong>：undo 用来回滚和提供历史版本；redo 用来宕机后把已提交但还没写到数据文件的修改补回来；binlog 是 MySQL 层的变更记录，用来做主从复制和按时间点恢复。</p><table><thead><tr><th>对比</th><th>undo log</th><th>redo log</th><th>binlog</th></tr></thead><tbody><tr><td>所属</td><td>InnoDB</td><td>InnoDB</td><td>MySQL Server 层</td></tr><tr><td>记录</td><td>怎么撤销</td><td>页改成了什么</td><td>每行改成了什么</td></tr><tr><td>用途</td><td>回滚、MVCC</td><td>崩溃恢复</td><td>复制、恢复到时间点、CDC</td></tr></tbody></table><ul><li>两阶段提交：先把 redo 标记为「准备好」，再写 binlog，最后标记「已提交」</li><li>崩溃恢复时看 binlog：binlog 里有这个事务就提交，没有就回滚，保证主库和从库、备份的数据一致</li><li>「双 1」配置：<code>innodb_flush_log_at_trx_commit=1</code>、<code>sync_binlog=1</code>（都是默认值），每次提交都刷盘，不丢数据</li></ul>`,4),o(`p`,null,[l[21]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/5_topic_transaction.html#_4%E3%80%81%E4%B8%A4%E9%98%B6%E6%AE%B5%E6%8F%90%E4%BA%A4%E4%B8%8E%E5%B4%A9%E6%BA%83%E6%81%A2%E5%A4%8D`},{default:r(()=>[...l[20]||=[i(`MySQL 事务与锁`,-1)]]),_:1})]),l[136]||=e(`<h2 id="二、索引" tabindex="-1"><a class="header-anchor" href="#二、索引"><span>二、索引</span></a></h2><h3 id="q6-innodb-为什么用-b-树-b-树真的不能做范围查询吗-三层-b-树能存多少行" tabindex="-1"><a class="header-anchor" href="#q6-innodb-为什么用-b-树-b-树真的不能做范围查询吗-三层-b-树能存多少行"><span>Q6：InnoDB 为什么用 B+ 树？B 树真的不能做范围查询吗？三层 B+ 树能存多少行？</span></a></h3><p><strong>一句话</strong>：B 树也能做范围查询，只是效率差。B+ 树非叶子节点只存键，一个节点能放更多键，树更矮；数据都在叶子上，叶子之间用链表串起来，范围查询找到起点后顺着往后读就行。</p><ul><li>二叉树（红黑树等）太高，千万数据要二十多层，每层一次磁盘读</li><li>B 树非叶子节点也存数据，放的键少、树更高；范围查询要上下来回跳</li><li>哈希只能做等值查询，不能范围、排序、前缀匹配</li><li>三层约 2000 万行：16KB 一页，非叶子页约放 1170 个指针，叶子页按每行 1KB 放 16 行，1170 × 1170 × 16 ≈ 2000 万</li></ul><p><strong>常见坑</strong>：2000 万不是分表阈值，行越宽这个数越小；它只说明点查只需读 2～3 页。</p>`,5),o(`p`,null,[l[23]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/4_topic_index.html#%E4%B8%80%E3%80%81b-%E6%A0%91%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84`},{default:r(()=>[...l[22]||=[i(`MySQL 索引`,-1)]]),_:1})]),l[137]||=e(`<h3 id="q7-聚簇索引和二级索引的区别-什么是回表和覆盖索引" tabindex="-1"><a class="header-anchor" href="#q7-聚簇索引和二级索引的区别-什么是回表和覆盖索引"><span>Q7：聚簇索引和二级索引的区别？什么是回表和覆盖索引？</span></a></h3><p><strong>一句话</strong>：主键索引就是聚簇索引，叶子上存整行数据；二级索引叶子上只存「索引列 + 主键」。用二级索引查别的列，要拿主键再去主键索引查一次，这叫回表；要的列二级索引上都有，就不用回表，这叫覆盖索引。</p><table><thead><tr><th>对比</th><th>聚簇索引</th><th>二级索引</th></tr></thead><tbody><tr><td>数量</td><td>每表一个</td><td>可以多个</td></tr><tr><td>叶子存什么</td><td>整行</td><td>索引列 + 主键</td></tr></tbody></table><ul><li>EXPLAIN 的 Extra 显示 <code>Using index</code> 才是覆盖索引</li><li>主键越长，每个二级索引都越大</li><li>回表的行很多时就是大量随机读，是慢查询的常见原因</li></ul>`,4),o(`p`,null,[l[25]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/4_topic_index.html#%E4%B8%89%E3%80%81%E8%81%9A%E7%B0%87%E7%B4%A2%E5%BC%95%E4%B8%8E%E4%BA%8C%E7%BA%A7%E7%B4%A2%E5%BC%95`},{default:r(()=>[...l[24]||=[i(`MySQL 索引`,-1)]]),_:1})]),l[138]||=e(`<h3 id="q8-联合索引的最左前缀原则是什么-范围条件之后的列完全用不上吗" tabindex="-1"><a class="header-anchor" href="#q8-联合索引的最左前缀原则是什么-范围条件之后的列完全用不上吗"><span>Q8：联合索引的最左前缀原则是什么？范围条件之后的列完全用不上吗？</span></a></h3><p><strong>一句话</strong>：联合索引 <code>(a, b, c)</code> 先按 a 排、a 相同再按 b 排，以此类推，所以必须从 a 开始连续用等值条件才能快速定位。遇到范围条件后，后面的列不能再缩小查找范围，但还能用来提前过滤，减少回表。</p><ul><li><code>a = 1 AND b = 2 AND c = 3</code>：三列都能用</li><li><code>a = 1 AND c = 3</code>：只用 a 定位，c 在索引上过滤</li><li><code>a = 1 AND b &gt; 2 AND c = 3</code>：用 a、b 定位，c 在索引上过滤</li><li>「在索引上过滤」叫索引下推（ICP），EXPLAIN 显示 <code>Using index condition</code></li><li>只查 <code>b = 2</code> 一般用不上；8.0 在条件合适时可以「跳跃扫描」（Skip Scan）</li></ul>`,3),o(`p`,null,[l[27]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/4_topic_index.html#%E5%85%AD%E3%80%81%E6%9C%80%E5%B7%A6%E5%89%8D%E7%BC%80%E5%8E%9F%E5%88%99`},{default:r(()=>[...l[26]||=[i(`MySQL 索引`,-1)]]),_:1})]),l[139]||=e(`<h3 id="q9-索引失效的常见场景有哪些" tabindex="-1"><a class="header-anchor" href="#q9-索引失效的常见场景有哪些"><span>Q9：索引失效的常见场景有哪些？</span></a></h3><p><strong>一句话</strong>：分两类：一是对索引列做了加工，索引的顺序用不上了；二是索引能用，但优化器算下来觉得全表扫描更便宜。到底走没走索引，以 <code>EXPLAIN</code> 为准。</p><ul><li>对列用函数或运算：<code>YEAR(create_time) = 2024</code>，改成时间范围条件</li><li>类型不一致：字符串列 <code>phone = 13800138000</code>（没加引号），列会被转换成数字</li><li>左模糊 <code>LIKE &#39;%abc&#39;</code>：开头不确定，没法定位；包含匹配用全文索引或 ES</li><li>OR 有一侧没索引、<code>!=</code>、<code>NOT IN</code>、区分度低（如 <code>status</code> 只有几种值）：优化器可能放弃索引</li><li>没有「命中超过 30% 就不走索引」这种固定规则，都是按成本估算</li></ul><p><strong>常见坑</strong>：关联的两张表字符集或排序规则不一致，JOIN 时一侧被转换，索引失效。</p>`,4),o(`p`,null,[l[29]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/4_topic_index.html#%E4%B8%83%E3%80%81%E7%B4%A2%E5%BC%95%E5%A4%B1%E6%95%88%E7%9A%84%E5%B8%B8%E8%A7%81%E5%9C%BA%E6%99%AF`},{default:r(()=>[...l[28]||=[i(`MySQL 索引`,-1)]]),_:1})]),l[140]||=e(`<h3 id="q10-深度分页如何优化" tabindex="-1"><a class="header-anchor" href="#q10-深度分页如何优化"><span>Q10：深度分页如何优化？</span></a></h3><p><strong>一句话</strong>：<code>LIMIT 100000, 20</code> 要先读出 10 万行再扔掉，<code>SELECT *</code> 时每行还要回表。要跳页就用延迟关联，只查下一页就用游标翻页。</p><ul><li>延迟关联：子查询在覆盖索引上只取 20 个 id，外层再按 id 查整行，只回表 20 次</li><li>游标翻页：记住上一页最后一条的排序值和 id，下一页用 <code>WHERE</code> 接着查，速度和页数无关</li><li>游标翻页不能随意跳到第 N 页；产品上也可以限制最大页数</li></ul><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">WHERE</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> user_id </span><span style="--shiki-light:#383A42;--shiki-dark:#56B6C2;">=</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> ? </span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">AND</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> (create_time </span><span style="--shiki-light:#383A42;--shiki-dark:#56B6C2;">&lt;</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> ? </span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">OR</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> (create_time </span><span style="--shiki-light:#383A42;--shiki-dark:#56B6C2;">=</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> ? </span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">AND</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> id </span><span style="--shiki-light:#383A42;--shiki-dark:#56B6C2;">&lt;</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> ?)) </span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">ORDER BY</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> create_time </span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">DESC</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">, id </span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">DESC</span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;"> LIMIT</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 20</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>常见坑</strong>：排序字段可能重复，游标必须带上 id，否则会漏数据或重复。</p>`,5),o(`p`,null,[l[31]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/4_topic_index.html#%E4%B9%9D%E3%80%81%E6%B7%B1%E5%BA%A6%E5%88%86%E9%A1%B5%E4%BC%98%E5%8C%96`},{default:r(()=>[...l[30]||=[i(`MySQL 索引`,-1)]]),_:1})]),l[141]||=e(`<h3 id="q11-如何设计合理的索引-唯一索引和普通索引怎么选" tabindex="-1"><a class="header-anchor" href="#q11-如何设计合理的索引-唯一索引和普通索引怎么选"><span>Q11：如何设计合理的索引？唯一索引和普通索引怎么选？</span></a></h3><p><strong>一句话</strong>：围绕高频查询建联合索引，尽量做到覆盖索引，控制索引数量。数据该唯一就用唯一索引，不要为了那点写入性能改成普通索引。</p><ul><li>该建：WHERE、JOIN、ORDER BY、GROUP BY 里常用、区分度高的列</li><li>列顺序：等值条件的列在前，范围条件的列在后；<code>WHERE a = ? ORDER BY b</code> 建 <code>(a, b)</code></li><li>慎建：区分度低的列单独建索引、频繁更新的列、很长的字符串；每个索引都会拖慢写入</li><li>「普通索引写入更快」靠的是 Change Buffer（先把修改攒在内存里），MySQL 8.4 默认已关闭它</li></ul><p><strong>常见坑</strong>：直接删索引有风险，先设为不可见观察：<code>ALTER TABLE t ALTER INDEX idx INVISIBLE</code>。</p>`,4),o(`p`,null,[l[33]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/4_topic_index.html#%E5%8D%81%E3%80%81%E7%B4%A2%E5%BC%95%E8%AE%BE%E8%AE%A1%E5%8E%9F%E5%88%99`},{default:r(()=>[...l[32]||=[i(`MySQL 索引`,-1)]]),_:1})]),l[142]||=e(`<h2 id="三、锁" tabindex="-1"><a class="header-anchor" href="#三、锁"><span>三、锁</span></a></h2><h3 id="q12-innodb-有哪些锁-record-lock、gap-lock、next-key-lock-的区别和加锁规则" tabindex="-1"><a class="header-anchor" href="#q12-innodb-有哪些锁-record-lock、gap-lock、next-key-lock-的区别和加锁规则"><span>Q12：InnoDB 有哪些锁？Record Lock、Gap Lock、Next-Key Lock 的区别和加锁规则？</span></a></h3><p><strong>一句话</strong>：行锁分共享锁（S）和排他锁（X）；按锁的范围分：Record Lock 锁一条记录，Gap Lock 锁两条记录之间的空隙，Next-Key Lock 是两者加起来。RR 下当前读默认加 Next-Key Lock，而且是加在扫描到的每条索引记录上。</p><table><thead><tr><th>锁</th><th>锁住什么</th></tr></thead><tbody><tr><td>Record Lock</td><td>一条索引记录</td></tr><tr><td>Gap Lock</td><td>记录之间的空隙，只防插入</td></tr><tr><td>Next-Key Lock</td><td>空隙 + 记录</td></tr><tr><td>插入意向锁</td><td>INSERT 前申请，会被空隙上的锁挡住</td></tr></tbody></table><ul><li>唯一索引等值查中了：只锁这一条；没查中：锁它所在的空隙</li><li>普通索引等值查：锁命中记录和它前后的空隙</li><li>RC 下基本不加间隙锁</li><li>实际加了哪些锁，看 <code>performance_schema.data_locks</code></li></ul>`,5),o(`p`,null,[l[35]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/5_topic_transaction.html#%E4%BA%94%E3%80%81%E9%94%81`},{default:r(()=>[...l[34]||=[i(`MySQL 事务与锁`,-1)]]),_:1})]),l[143]||=e(`<h3 id="q13-没走索引的-update-会锁住哪些行" tabindex="-1"><a class="header-anchor" href="#q13-没走索引的-update-会锁住哪些行"><span>Q13：没走索引的 UPDATE 会锁住哪些行？</span></a></h3><p><strong>一句话</strong>：InnoDB 不会把行锁升级成表锁，但锁是加在扫描到的记录上的。没走索引就要扫全表，RR 下每一行和每个空隙都被锁住，效果上整张表都不能更新和插入。</p><ul><li>锁一直持有到事务结束</li><li>RC 下不满足条件的行判断完就释放锁，影响小得多，但全表扫描本身还是慢</li><li>走了索引但范围很大，同样会锁住大量记录</li></ul><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">UPDATE</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> orders </span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">SET</span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;"> status</span><span style="--shiki-light:#383A42;--shiki-dark:#56B6C2;"> =</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 2</span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;"> WHERE</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> remark </span><span style="--shiki-light:#383A42;--shiki-dark:#56B6C2;">=</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &#39;urgent&#39;</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">;  </span><span style="--shiki-light:#A0A1A7;--shiki-light-font-style:italic;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">-- remark 无索引：等于锁全表</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>常见坑</strong>：UPDATE、DELETE、<code>FOR UPDATE</code> 上线前用 EXPLAIN 确认走了索引；大批量修改按主键范围分批执行。</p>`,5),o(`p`,null,[l[37]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/3_fallible_point.html#_3%E3%80%81select-for-update-%E9%94%81%E4%BD%8F%E4%BA%86%E6%95%B4%E5%BC%A0%E8%A1%A8`},{default:r(()=>[...l[36]||=[i(`MySQL 避坑指南`,-1)]]),_:1})]),l[144]||=e(`<h3 id="q14-死锁是怎么产生的-如何排查和预防" tabindex="-1"><a class="header-anchor" href="#q14-死锁是怎么产生的-如何排查和预防"><span>Q14：死锁是怎么产生的？如何排查和预防？</span></a></h3><p><strong>一句话</strong>：两个事务互相等对方手里的锁，谁也走不下去就是死锁。InnoDB 会自动发现，回滚其中一个，返回错误 1213。</p><ul><li>常见原因一：两个事务加锁顺序相反（A 先锁 1 再锁 2，B 先锁 2 再锁 1）</li><li>常见原因二：RR 下两个事务都先 <code>FOR UPDATE</code> 查一个不存在的行（都拿到同一个空隙锁），再各自 INSERT，互相被对方的空隙锁挡住</li><li>排查：<code>SHOW ENGINE INNODB STATUS</code> 看最近一次死锁；开 <code>innodb_print_all_deadlocks=ON</code> 把每次死锁都记进错误日志</li><li>预防：统一加锁顺序、拆小事务、条件走索引；「不存在就插入」改用唯一键 + <code>INSERT ... ON DUPLICATE KEY UPDATE</code></li></ul><p><strong>常见坑</strong>：应用捕获 1213 后要重试整个事务，不是只重试那一条 SQL。</p>`,4),o(`p`,null,[l[39]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/5_topic_transaction.html#_6%E3%80%81%E6%AD%BB%E9%94%81`},{default:r(()=>[...l[38]||=[i(`MySQL 事务与锁`,-1)]]),_:1})]),l[145]||=e(`<h3 id="q15-高并发下如何安全地修改同一行数据" tabindex="-1"><a class="header-anchor" href="#q15-高并发下如何安全地修改同一行数据"><span>Q15：高并发下如何安全地修改同一行数据？</span></a></h3><p><strong>一句话</strong>：最简单的是带条件的原子 UPDATE；逻辑复杂、冲突少用乐观锁（版本号），冲突多用悲观锁（<code>FOR UPDATE</code>）。单行写入量太大（如秒杀扣库存）时，要靠 Redis 预扣、分桶等系统层面的办法。</p><table><thead><tr><th>方式</th><th>写法</th><th>适用</th></tr></thead><tbody><tr><td>条件 UPDATE</td><td><code>SET num = num - 1 WHERE id = ? AND num &gt;= 1</code>，看影响行数</td><td>扣减、计数</td></tr><tr><td>乐观锁</td><td><code>WHERE id = ? AND version = ?</code>，影响 0 行就重试</td><td>冲突少</td></tr><tr><td>悲观锁</td><td>事务里先 <code>SELECT ... FOR UPDATE</code> 再改</td><td>冲突多</td></tr><tr><td>热点治理</td><td>Redis 预扣、分桶库存、合并写</td><td>单行每秒上千次写</td></tr></tbody></table><ul><li>条件要命中主键或唯一索引，否则锁的范围会变大（见 Q13）</li><li>跨服务、跨库的互斥要用分布式锁</li></ul>`,4),o(`p`,null,[l[42]||=i(`→ 详见 `,-1),s(m,{to:`/interview/13_high_con.html#q30-%E7%A7%92%E6%9D%80%E5%9C%BA%E6%99%AF%E4%B8%8B%E5%90%8C%E4%B8%80%E8%A1%8C%E5%BA%93%E5%AD%98%E7%9A%84%E9%AB%98%E5%B9%B6%E5%8F%91%E6%89%A3%E5%87%8F%E5%A6%82%E4%BD%95%E4%BC%98%E5%8C%96`},{default:r(()=>[...l[40]||=[i(`高并发面试题解答`,-1)]]),_:1}),l[43]||=i(`、`,-1),s(m,{to:`/high-con/6_hotspot.html#%E4%B8%89%E3%80%81%E5%86%99%E7%83%AD%E7%82%B9-%E7%83%AD%E7%82%B9%E8%A1%8C%E6%9B%B4%E6%96%B0`},{default:r(()=>[...l[41]||=[i(`热点问题`,-1)]]),_:1})]),l[146]||=e(`<h2 id="四、存储引擎" tabindex="-1"><a class="header-anchor" href="#四、存储引擎"><span>四、存储引擎</span></a></h2><h3 id="q16-innodb-和-myisam-的区别" tabindex="-1"><a class="header-anchor" href="#q16-innodb-和-myisam-的区别"><span>Q16：InnoDB 和 MyISAM 的区别？</span></a></h3><p><strong>一句话</strong>：InnoDB 支持事务、行锁、外键和崩溃后自动恢复；MyISAM 只有表锁、没有事务，崩溃后容易坏表。InnoDB 早就是默认引擎，新项目没有理由用 MyISAM。</p><table><thead><tr><th>对比</th><th>InnoDB</th><th>MyISAM</th></tr></thead><tbody><tr><td>事务</td><td>支持</td><td>不支持</td></tr><tr><td>锁</td><td>行锁</td><td>表锁</td></tr><tr><td>崩溃恢复</td><td>靠 redo 自动恢复</td><td>容易损坏</td></tr><tr><td>索引</td><td>聚簇索引</td><td>索引存行地址</td></tr><tr><td><code>COUNT(*)</code></td><td>要扫描索引</td><td>直接返回存好的行数</td></tr></tbody></table>`,4),o(`p`,null,[l[45]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/8_topic_innodb.html#%E4%B8%83%E3%80%81%E5%AD%98%E5%82%A8%E5%BC%95%E6%93%8E%E5%AF%B9%E6%AF%94`},{default:r(()=>[...l[44]||=[i(`InnoDB 存储结构`,-1)]]),_:1})]),l[147]||=o(`h3`,{id:`q17-innodb-为什么推荐自增主键-不定义主键会怎样`,tabindex:`-1`},[o(`a`,{class:`header-anchor`,href:`#q17-innodb-为什么推荐自增主键-不定义主键会怎样`},[o(`span`,null,`Q17：InnoDB 为什么推荐自增主键？不定义主键会怎样？`)])],-1),l[148]||=o(`p`,null,[o(`strong`,null,`一句话`),i(`：数据按主键顺序存放。自增主键让新行总是加在最后，不用在中间插队挪数据（页分裂）；主键短，所有二级索引也更小。随机主键（如 UUID v4）会到处插，页分裂多、空间浪费大。`)],-1),l[149]||=o(`ul`,null,[o(`li`,null,`分布式下要全局唯一又大致递增：用雪花 ID、号段或 UUID v7`),o(`li`,null,`自增 ID 不连续是正常的（回滚、批量插入都会跳号），不要拿它当业务序号`),o(`li`,null,`不定义主键：InnoDB 先找一个非空唯一索引当主键，找不到就用隐藏的 6 字节 row_id`),o(`li`,null,`没有主键的表在主从复制时，每次行变更从库都要全表扫描找行，造成复制延迟`)],-1),o(`p`,null,[l[47]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/4_topic_index.html#_1%E3%80%81%E8%81%9A%E7%B0%87%E7%B4%A2%E5%BC%95-clustered-index`},{default:r(()=>[...l[46]||=[i(`MySQL 索引`,-1)]]),_:1})]),l[150]||=e(`<h3 id="q18-什么是页-innodb-的存储层次和行溢出是怎样的" tabindex="-1"><a class="header-anchor" href="#q18-什么是页-innodb-的存储层次和行溢出是怎样的"><span>Q18：什么是页？InnoDB 的存储层次和行溢出是怎样的？</span></a></h3><p><strong>一句话</strong>：页是 InnoDB 读写磁盘和缓存数据的最小单位，默认 16KB，B+ 树的一个节点就是一页。层次从大到小是：表空间 → 段 → 区 → 页 → 行。</p><ul><li>表空间：通常每张表一个 <code>.ibd</code> 文件，存这张表的数据和索引</li><li>段：每个索引分叶子段和非叶子段；区：64 个连续页（1MB），让相关的页在磁盘上挨着</li><li>行溢出：一页至少放两行，单行超过约 8KB 时，最长的变长字段整个挪到单独的溢出页，行里只留一个指针</li><li>页大小只能在初始化实例时设定，之后不能改</li></ul><p><strong>常见坑</strong>：大字段（富文本、大 JSON）拆到附表，否则每页放的行变少，读的时候还要额外读溢出页。</p>`,4),o(`p`,null,[l[49]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/8_topic_innodb.html#%E4%B8%80%E3%80%81%E8%A1%A8%E7%A9%BA%E9%97%B4%E5%B1%82%E6%AC%A1-%E6%AE%B5%E3%80%81%E5%8C%BA%E3%80%81%E9%A1%B5%E3%80%81%E8%A1%8C`},{default:r(()=>[...l[48]||=[i(`InnoDB 存储结构`,-1)]]),_:1})]),l[151]||=e(`<h3 id="q19-buffer-pool-如何管理内存-double-write-解决什么问题-mysql-偶尔「抖」一下是什么原因" tabindex="-1"><a class="header-anchor" href="#q19-buffer-pool-如何管理内存-double-write-解决什么问题-mysql-偶尔「抖」一下是什么原因"><span>Q19：Buffer Pool 如何管理内存？Double Write 解决什么问题？MySQL 偶尔「抖」一下是什么原因？</span></a></h3><p><strong>一句话</strong>：Buffer Pool 是 InnoDB 在内存里缓存数据页的地方，用改进的 LRU 淘汰旧页。修改过的页（脏页）由后台慢慢写回磁盘；redo 快写满或空闲页不够时被迫集中写回，就是 MySQL 偶尔「抖一下」的常见原因。</p><ul><li>改进的 LRU：新读进来的页先放在「冷区」，过 1 秒后再被访问才进「热区」，防止一次全表扫描把热数据挤掉</li><li>Double Write：16KB 的页写到一半断电，这页就坏了，redo 也没法在坏页上恢复；所以先把页完整写一份副本，坏了就用副本修</li><li>调优：<code>innodb_buffer_pool_size</code> 设为物理内存的 50%～75%；redo 容量留足；<code>innodb_io_capacity</code> 按磁盘能力设置</li></ul>`,3),o(`p`,null,[l[51]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/8_topic_innodb.html#%E4%B8%89%E3%80%81buffer-pool`},{default:r(()=>[...l[50]||=[i(`InnoDB 存储结构`,-1)]]),_:1})]),l[152]||=e(`<h2 id="五、sql-执行与优化" tabindex="-1"><a class="header-anchor" href="#五、sql-执行与优化"><span>五、SQL 执行与优化</span></a></h2><h3 id="q20-一条-sql-的执行流程是什么-select-和-update-有何不同" tabindex="-1"><a class="header-anchor" href="#q20-一条-sql-的执行流程是什么-select-和-update-有何不同"><span>Q20：一条 SQL 的执行流程是什么？SELECT 和 UPDATE 有何不同？</span></a></h3><p><strong>一句话</strong>：连接器验证身份 → 分析器检查语法和表、列是否存在 → 优化器选索引和 JOIN 顺序 → 执行器调用存储引擎取数据。UPDATE 多了写的步骤：加锁、写 undo、改内存里的页、写 redo 和 binlog，提交时走两阶段提交（见 Q5）。</p><ul><li>查询缓存在 8.0 已经删除</li><li>连接空闲超过 <code>wait_timeout</code>（默认 8 小时）会被服务端断开</li><li>优化器靠统计信息估算成本，统计信息不准就可能选错索引（见 Q22）</li><li>为什么不直接改磁盘上的数据：那是随机写，很慢；先顺序写日志（WAL，先写日志后写数据），数据页由后台慢慢刷</li></ul>`,4),o(`p`,null,[l[53]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/6_topic_execution.html#%E4%BA%8C%E3%80%81%E5%90%84%E7%BB%84%E4%BB%B6%E8%81%8C%E8%B4%A3`},{default:r(()=>[...l[52]||=[i(`SQL 执行流程`,-1)]]),_:1})]),l[153]||=e(`<h3 id="q21-explain-各字段的含义-type-从好到差的顺序是什么" tabindex="-1"><a class="header-anchor" href="#q21-explain-各字段的含义-type-从好到差的顺序是什么"><span>Q21：EXPLAIN 各字段的含义？type 从好到差的顺序是什么？</span></a></h3><p><strong>一句话</strong>：重点看四样：<code>type</code>（怎么访问表）、<code>key</code>（用了哪个索引）、<code>rows</code>（估计扫多少行）、<code>Extra</code>（有没有回表、额外排序、临时表）。type 常见的从好到差是 <code>const</code> &gt; <code>eq_ref</code> &gt; <code>ref</code> &gt; <code>range</code> &gt; <code>index</code> &gt; <code>ALL</code>，核心查询至少要到 <code>range</code>。</p><ul><li><code>key_len</code>：看联合索引实际用到了几列</li><li>Extra 里 <code>Using index</code> 是覆盖索引；<code>Using filesort</code> 是额外排序；<code>Using temporary</code> 用了临时表</li><li><code>index</code> 是扫整个索引，<code>ALL</code> 是扫全表，都要警惕</li><li><code>EXPLAIN ANALYZE</code> 会真正执行语句，给出实际耗时和行数，能和估算对比</li></ul><p><strong>常见坑</strong>：<code>Using filesort</code> 不一定是磁盘排序，数据超过排序缓冲区才会落盘。</p>`,4),o(`p`,null,[l[55]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/7_topic_explain.html#%E4%B8%80%E3%80%81explain-%E5%AD%97%E6%AE%B5%E6%80%BB%E8%A7%88`},{default:r(()=>[...l[54]||=[i(`EXPLAIN 与 SQL 优化`,-1)]]),_:1})]),l[154]||=e(`<h3 id="q22-慢查询如何定位-优化器选错索引怎么办" tabindex="-1"><a class="header-anchor" href="#q22-慢查询如何定位-优化器选错索引怎么办"><span>Q22：慢查询如何定位？优化器选错索引怎么办？</span></a></h3><p><strong>一句话</strong>：打开慢查询日志 → 用 <code>pt-query-digest</code> 按总耗时找出最该优化的 SQL → 用 <code>EXPLAIN</code> 看执行计划。选错索引时从轻到重处理：更新统计信息、建直方图、加索引提示，最后才 <code>FORCE INDEX</code>。</p><ul><li>慢日志：<code>slow_query_log=1</code>，<code>long_query_time</code> 设到 1 秒或更低</li><li>正在跑的语句看 <code>SHOW PROCESSLIST</code>；历史 TOP 语句看 <code>sys.statement_analysis</code></li><li><code>ANALYZE TABLE</code> 更新统计信息；数据分布不均的列建直方图，让优化器估得更准</li><li>补合适的联合索引、改写 SQL，通常比强制指定索引更长久</li></ul>`,3),o(`p`,null,[l[58]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/7_topic_explain.html#%E5%9B%9B%E3%80%81%E6%85%A2-sql-%E5%AE%9A%E4%BD%8D`},{default:r(()=>[...l[56]||=[i(`EXPLAIN 与 SQL 优化`,-1)]]),_:1}),l[59]||=i(`、`,-1),s(m,{to:`/database/1_mysql/6_topic_execution.html#_4%E3%80%81%E4%BC%98%E5%8C%96%E5%99%A8`},{default:r(()=>[...l[57]||=[i(`SQL 执行流程`,-1)]]),_:1})]),l[155]||=e(`<h3 id="q23-count-、count-1-、count-字段-的区别" tabindex="-1"><a class="header-anchor" href="#q23-count-、count-1-、count-字段-的区别"><span>Q23：<code>COUNT(*)</code>、<code>COUNT(1)</code>、<code>COUNT(字段)</code> 的区别？</span></a></h3><p><strong>一句话</strong>：<code>COUNT(*)</code> 和 <code>COUNT(1)</code> 一样快，都是数行数；<code>COUNT(主键)</code> 要取出主键值，稍慢；<code>COUNT(普通字段)</code> 只数不为 NULL 的值，意思都不一样。</p><ul><li>InnoDB 不存总行数：不同事务看到的行数可能不同（MVCC），所以 <code>COUNT(*)</code> 必须扫描</li><li>没有 WHERE 时，MySQL 会挑最小的索引来扫，比扫主键索引快</li><li>大表要总数：能接受近似值就用 <code>information_schema.TABLES</code> 的估算值；要精确又频繁，就单独维护一张计数表</li></ul>`,3),o(`p`,null,[l[61]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/7_topic_explain.html#%E5%85%AD%E3%80%81count-%E7%9A%84%E6%80%A7%E8%83%BD`},{default:r(()=>[...l[60]||=[i(`EXPLAIN 与 SQL 优化`,-1)]]),_:1})]),l[156]||=e(`<h3 id="q24-join-是怎么执行的-8-0-20-之后-bnl-去哪了" tabindex="-1"><a class="header-anchor" href="#q24-join-是怎么执行的-8-0-20-之后-bnl-去哪了"><span>Q24：JOIN 是怎么执行的？8.0.20 之后 BNL 去哪了？</span></a></h3><p><strong>一句话</strong>：被关联的表在关联字段上有索引时，驱动表每一行都拿去索引里查一次（Index Nested-Loop）；没有索引时，8.0.18 起用 Hash Join：把小的一边放进内存建哈希表，另一边逐行去查。8.0.20 起 Hash Join 完全取代了老的 BNL（块嵌套循环）。</p><ul><li>EXPLAIN 显示 <code>Using join buffer (hash join)</code>，说明被关联的表没有可用索引</li><li>给关联字段加索引，比依赖 Hash Join 更好</li><li>「小表驱动大表」的「小」指过滤后参与 JOIN 的数据量，优化器一般能选对</li><li>关联字段的类型、字符集要一致，否则索引失效</li></ul>`,3),o(`p`,null,[l[63]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/7_topic_explain.html#%E4%B8%83%E3%80%81join-%E5%8E%9F%E7%90%86%E4%B8%8E%E4%BC%98%E5%8C%96`},{default:r(()=>[...l[62]||=[i(`EXPLAIN 与 SQL 优化`,-1)]]),_:1})]),l[157]||=e(`<h3 id="q25-大表-ddl-为什么会卡住整张表-online-ddl-和-gh-ost-怎么选" tabindex="-1"><a class="header-anchor" href="#q25-大表-ddl-为什么会卡住整张表-online-ddl-和-gh-ost-怎么选"><span>Q25：大表 DDL 为什么会卡住整张表？Online DDL 和 gh-ost 怎么选？</span></a></h3><p><strong>一句话</strong>：改表结构要拿表的元数据写锁（MDL），只要有没提交的事务访问过这张表，DDL 就得等；而 DDL 一排队，后面所有读写这张表的请求都排在它后面，整张表就卡住了。真正危险的往往是等锁，不是 DDL 本身。</p><table><thead><tr><th>方式</th><th>做法</th><th>能否同时读写</th></tr></thead><tbody><tr><td>INSTANT</td><td>只改元数据，秒完成</td><td>能</td></tr><tr><td>INPLACE</td><td>引擎内部完成，可能重建表</td><td>大多能</td></tr><tr><td>COPY</td><td>建新表逐行复制</td><td>不能</td></tr></tbody></table><ul><li>加列、删列在 8.0.29 起是 INSTANT；改列类型、改字符集要 COPY</li><li>执行前先查长事务，并把 DDL 会话的 <code>lock_wait_timeout</code> 设短，等不到就放弃，别堵住业务</li><li>千万行以上要重建的表用 gh-ost（读 binlog 同步增量、可限速）或 pt-online-schema-change（用触发器同步）</li></ul>`,4),o(`p`,null,[l[65]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/3_fallible_point.html#%E4%B8%83%E3%80%81%E5%A4%A7%E8%A1%A8-ddl-%E4%B8%8E-online-ddl`},{default:r(()=>[...l[64]||=[i(`MySQL 避坑指南`,-1)]]),_:1})]),l[158]||=e(`<h2 id="六、主从与高可用" tabindex="-1"><a class="header-anchor" href="#六、主从与高可用"><span>六、主从与高可用</span></a></h2><h3 id="q26-mysql-主从复制的原理-binlog-有哪几种格式" tabindex="-1"><a class="header-anchor" href="#q26-mysql-主从复制的原理-binlog-有哪几种格式"><span>Q26：MySQL 主从复制的原理？binlog 有哪几种格式？</span></a></h3><p><strong>一句话</strong>：主库把变更写进 binlog；从库的接收线程把 binlog 拉过来存成 relay log（中继日志），再由回放线程执行一遍。默认是异步复制。binlog 有 ROW、STATEMENT、MIXED 三种格式，只推荐 ROW。</p><table><thead><tr><th>格式</th><th>记录什么</th><th>现状</th></tr></thead><tbody><tr><td>ROW</td><td>每行改前改后的数据</td><td>默认，CDC 依赖它</td></tr><tr><td>STATEMENT</td><td>SQL 原文</td><td><code>NOW()</code>、<code>UUID()</code> 等可能导致主从不一致</td></tr><tr><td>MIXED</td><td>自动切换</td><td>遗留格式</td></tr></tbody></table><ul><li>从库默认多线程并行回放</li><li>8.4 删除了所有 MASTER / SLAVE 语法，改用 <code>CHANGE REPLICATION SOURCE TO</code>、<code>START REPLICA</code>、<code>SHOW REPLICA STATUS</code></li></ul>`,5),o(`p`,null,[l[67]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/9_topic_replication.html#%E4%BA%8C%E3%80%81%E5%A4%8D%E5%88%B6%E5%8E%9F%E7%90%86`},{default:r(()=>[...l[66]||=[i(`MySQL 主从与高可用`,-1)]]),_:1})]),l[159]||=e(`<h3 id="q27-gtid-和半同步复制分别解决什么问题" tabindex="-1"><a class="header-anchor" href="#q27-gtid-和半同步复制分别解决什么问题"><span>Q27：GTID 和半同步复制分别解决什么问题？</span></a></h3><p><strong>一句话</strong>：GTID 给每个事务一个全局编号，切换主库时从库能自动知道从哪接着复制，不用人工找 binlog 文件和位置。半同步解决异步复制下主库宕机丢最后几笔事务的问题：主库提交时至少等一个从库确认收到。</p><table><thead><tr><th>等待时机</th><th>主库什么时候等</th><th>切换后</th></tr></thead><tbody><tr><td><code>AFTER_SYNC</code>（默认）</td><td>写完 binlog、提交前</td><td>不会出现「旧主读到过、新主没有」</td></tr><tr><td><code>AFTER_COMMIT</code></td><td>提交后、返回客户端前</td><td>可能别人读到了，新主上却没有</td></tr></tbody></table><ul><li>GTID 格式是 <code>源库 UUID:序号</code>，开启自动定位用 <code>SOURCE_AUTO_POSITION=1</code></li><li>半同步等太久（默认 10 秒）会自动退回异步，要监控这种降级</li></ul>`,4),o(`p`,null,[l[69]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/9_topic_replication.html#%E4%B8%89%E3%80%81gtid-%E5%A4%8D%E5%88%B6`},{default:r(()=>[...l[68]||=[i(`MySQL 主从与高可用`,-1)]]),_:1})]),l[160]||=e(`<h3 id="q28-主从延迟的原因和解决办法-为什么-seconds-behind-source-不可靠" tabindex="-1"><a class="header-anchor" href="#q28-主从延迟的原因和解决办法-为什么-seconds-behind-source-不可靠"><span>Q28：主从延迟的原因和解决办法？为什么 <code>Seconds_Behind_Source</code> 不可靠？</span></a></h3><p><strong>一句话</strong>：延迟主要来自主库的大事务和大表 DDL、从库回放不够并行、从库在跑大查询、没有主键的表。解决办法是拆小事务、所有表加主键、开多线程回放；业务上对实时性要求高的读走主库。</p><ul><li>无主键表：ROW 格式下每改一行，从库都要全表扫描找这一行</li><li><code>Seconds_Behind_Source</code> 只看正在回放的事件，回放线程空闲时显示 0，哪怕事件根本没传过来</li><li>更准的监控：用 <code>pt-heartbeat</code> 在主库定时写心跳时间，从库读出来比较</li><li>读己之写：拿到自己事务的 GTID，从库读前用 <code>WAIT_FOR_EXECUTED_GTID_SET</code> 等它回放完</li></ul>`,3),o(`p`,null,[l[71]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/9_topic_replication.html#%E4%BA%94%E3%80%81%E5%A4%8D%E5%88%B6%E5%BB%B6%E8%BF%9F%E4%B8%8E%E5%A4%9A%E7%BA%BF%E7%A8%8B%E5%9B%9E%E6%94%BE`},{default:r(()=>[...l[70]||=[i(`MySQL 主从与高可用`,-1)]]),_:1})]),l[161]||=e(`<h3 id="q29-mysql-有哪几种高可用方案" tabindex="-1"><a class="header-anchor" href="#q29-mysql-有哪几种高可用方案"><span>Q29：MySQL 有哪几种高可用方案？</span></a></h3><p><strong>一句话</strong>：自建首选官方的 InnoDB Cluster（组复制 MGR + MySQL Shell + MySQL Router），自动选主、切换不丢已提交事务；跨地域再加 ClusterSet；上云直接用托管服务。MHA 多年没更新，不建议新建。</p><table><thead><tr><th>方案</th><th>特点</th></tr></thead><tbody><tr><td>主从 + 半同步 + 切换工具</td><td>灵活，切换和防脑裂要自己保证</td></tr><tr><td>InnoDB Cluster</td><td>多数派确认，自动选主，官方首选</td></tr><tr><td>InnoDB ClusterSet</td><td>多个 Cluster 跨地域容灾</td></tr><tr><td>InnoDB ReplicaSet</td><td>异步复制，手动切换</td></tr><tr><td>云托管（RDS、Aurora 等）</td><td>看切换时间和丢数据承诺</td></tr></tbody></table><ul><li>MGR 默认单主，最多 9 个成员，成员应在同一地域</li><li>读写分离：应用内用 ShardingSphere-JDBC，或用 MySQL Router、ProxySQL 做代理</li></ul>`,4),o(`p`,null,[l[73]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/9_topic_replication.html#%E5%85%AD%E3%80%81%E9%AB%98%E5%8F%AF%E7%94%A8%E6%96%B9%E6%A1%88`},{default:r(()=>[...l[72]||=[i(`MySQL 主从与高可用`,-1)]]),_:1})]),l[162]||=e(`<h3 id="q30-mysql-8-0-停止支持后如何升级-8-4-lts-有哪些需要注意的变化" tabindex="-1"><a class="header-anchor" href="#q30-mysql-8-0-停止支持后如何升级-8-4-lts-有哪些需要注意的变化"><span>Q30：MySQL 8.0 停止支持后如何升级？8.4 LTS 有哪些需要注意的变化？</span></a></h3><p><strong>一句话</strong>：8.0 已在 2026 年 4 月停止维护，应升级到 8.4 LTS，之后再到 9.7 LTS；只能一个 LTS 一个 LTS 地升，不能跳。8.4 的风险主要是删掉了一些语法和配置，以及 InnoDB 默认值变了。</p><ul><li>复制语法：MASTER / SLAVE 全部删除，监控脚本、高可用组件、CDC 工具要先确认兼容</li><li>配置项：<code>expire_logs_days</code> 等已删除，留在 my.cnf 里会启动失败</li><li>认证：<code>mysql_native_password</code> 默认不加载，先升级驱动，再把账号改成 <code>caching_sha2_password</code></li><li>默认值：Change Buffer、自适应哈希索引默认关闭，<code>innodb_io_capacity</code> 调大，要在预发环境压测</li><li>步骤：用 MySQL Shell 的 <code>util.checkForServerUpgrade()</code> 预检 → 清理配置 → 先升从库再切主</li></ul><p><strong>常见坑</strong>：8.4 不能原地降回 8.0，回退只能靠备份或逻辑复制。</p>`,4),o(`p`,null,[l[75]||=i(`→ 详见 `,-1),s(m,{to:`/database/1_mysql/1_feature.html#%E4%B8%83%E3%80%818-0-%E5%8D%87%E7%BA%A7%E5%88%B0-8-4-%E7%9A%84%E6%A3%80%E6%9F%A5%E6%B8%85%E5%8D%95`},{default:r(()=>[...l[74]||=[i(`MySQL 版本特性`,-1)]]),_:1})]),l[163]||=e(`<h2 id="七、postgresql" tabindex="-1"><a class="header-anchor" href="#七、postgresql"><span>七、PostgreSQL</span></a></h2><h3 id="q31-postgresql-与-mysql-的关键差异-如何选择" tabindex="-1"><a class="header-anchor" href="#q31-postgresql-与-mysql-的关键差异-如何选择"><span>Q31：PostgreSQL 与 MySQL 的关键差异？如何选择？</span></a></h3><p><strong>一句话</strong>：最根本的区别在存储方式：PG 的数据放在堆表里，所有索引都直接指向行的物理位置，没有聚簇索引；旧版本数据留在表里，靠 VACUUM 清理；每个连接是一个进程。功能上 PG 的 SQL 支持、JSONB 和扩展更强。</p><table><thead><tr><th>对比</th><th>MySQL InnoDB</th><th>PostgreSQL</th></tr></thead><tbody><tr><td>存储</td><td>聚簇索引</td><td>堆表</td></tr><tr><td>默认隔离级别</td><td>RR</td><td>RC</td></tr><tr><td>旧版本清理</td><td>undo + purge</td><td>VACUUM</td></tr><tr><td>连接</td><td>每连接一个线程</td><td>每连接一个进程，要配连接池</td></tr><tr><td>DDL 能否回滚</td><td>不能</td><td>大多能</td></tr></tbody></table><ul><li>常规业务、团队熟 MySQL、分库分表和 CDC 工具成熟 → MySQL</li><li>复杂查询、地理信息、JSON 文档、向量检索 → PostgreSQL（PostGIS、pgvector 等扩展）</li></ul><p><strong>常见坑</strong>：从 MySQL 迁到 PG，表名、列名不加双引号会一律变成小写。</p>`,6),o(`p`,null,[l[77]||=i(`→ 详见 `,-1),s(m,{to:`/database/2_postgresql/0_overview.html#%E4%BA%8C%E3%80%81%E4%B8%8E-mysql-%E7%9A%84%E5%B7%AE%E5%BC%82-java-%E5%BC%80%E5%8F%91%E8%A7%86%E8%A7%92`},{default:r(()=>[...l[76]||=[i(`PostgreSQL 基础`,-1)]]),_:1})]),l[164]||=e(`<h3 id="q32-pg-的-mvcc-与-innodb-有何不同-rr-下什么时候会报-40001" tabindex="-1"><a class="header-anchor" href="#q32-pg-的-mvcc-与-innodb-有何不同-rr-下什么时候会报-40001"><span>Q32：PG 的 MVCC 与 InnoDB 有何不同？RR 下什么时候会报 40001？</span></a></h3><p><strong>一句话</strong>：InnoDB 是直接改行，旧值放进 undo；PG 不改旧行，UPDATE 等于把旧行标记为作废、再插入一行新的。PG 的 RR 下，要改的行在你开始之后被别人改过并提交了，就直接报 40001 错误，而不是像 InnoDB 那样基于最新值接着改。</p><table><thead><tr><th>场景</th><th>InnoDB RR</th><th>PostgreSQL RR</th></tr></thead><tbody><tr><td>防幻读</td><td>快照读 + 间隙锁</td><td>快照本身就没有幻读，不需要间隙锁</td></tr><tr><td>并发改同一行</td><td>读最新版本继续改</td><td>报 40001，应用重试</td></tr></tbody></table><ul><li>PG 默认 RC：遇到并发更新会等对方提交，然后基于新值重新判断条件再改，不报错</li><li>Java 里在 RR / SERIALIZABLE 下捕获 40001，在事务方法外层重试整个事务</li><li>PG 的行锁记在行上，不占内存锁表，锁再多行也不会升级</li></ul>`,4),o(`p`,null,[l[79]||=i(`→ 详见 `,-1),s(m,{to:`/database/2_postgresql/2_topic_mvcc.html#%E4%B8%89%E3%80%81%E9%9A%94%E7%A6%BB%E7%BA%A7%E5%88%AB-%E5%86%99%E7%BB%99-mysql-%E7%94%A8%E6%88%B7`},{default:r(()=>[...l[78]||=[i(`MVCC 与 VACUUM`,-1)]]),_:1})]),l[165]||=e(`<h3 id="q33-vacuum-解决什么问题-hot-更新、表膨胀和-xid-回卷怎么处理" tabindex="-1"><a class="header-anchor" href="#q33-vacuum-解决什么问题-hot-更新、表膨胀和-xid-回卷怎么处理"><span>Q33：VACUUM 解决什么问题？HOT 更新、表膨胀和 XID 回卷怎么处理？</span></a></h3><p><strong>一句话</strong>：PG 的 UPDATE、DELETE 会留下作废的旧行，VACUUM 负责把它们的空间回收复用，还负责「冻结」老数据。清理不及时会导致表膨胀，严重时事务 ID 用完（XID 回卷），数据库会停止写入。</p><ul><li>HOT 更新：没改被索引的列、页里还有空位时，新版本放同一页，不用改索引；更新频繁的表可设 <code>fillfactor=85</code> 预留空间</li><li>表膨胀：热点表把 autovacuum 调得更勤；已膨胀的大表用 <code>pg_repack</code> 在线重建</li><li>XID 回卷：事务 ID 只有 32 位会绕回，要监控 <code>age(datfrozenxid)</code></li><li>清理卡住的常见原因：长事务、废弃的复制槽；用 <code>idle_in_transaction_session_timeout</code> 限制长事务</li></ul><p><strong>常见坑</strong>：不要关闭 autovacuum；<code>VACUUM FULL</code> 会锁全表，只能在停服窗口用。</p>`,4),o(`p`,null,[l[81]||=i(`→ 详见 `,-1),s(m,{to:`/database/2_postgresql/2_topic_mvcc.html#%E4%BA%94%E3%80%81vacuum`},{default:r(()=>[...l[80]||=[i(`MVCC 与 VACUUM`,-1)]]),_:1})]),l[166]||=e(`<h3 id="q34-gin、gist、brin-等索引分别适合什么场景" tabindex="-1"><a class="header-anchor" href="#q34-gin、gist、brin-等索引分别适合什么场景"><span>Q34：GIN、GiST、BRIN 等索引分别适合什么场景？</span></a></h3><p><strong>一句话</strong>：B-tree 是默认，管等值、范围、排序；GIN 是倒排索引，管「包含」类查询（JSONB、数组、全文检索）；GiST 管地理位置和范围重叠；BRIN 只记每一块数据的最小最大值，适合按时间追加的超大表。</p><table><thead><tr><th>查询特征</th><th>推荐</th></tr></thead><tbody><tr><td>等值、范围、排序</td><td>B-tree</td></tr><tr><td>JSONB 任意属性、数组包含、全文检索</td><td>GIN</td></tr><tr><td>地理位置、范围重叠、最近邻</td><td>GiST</td></tr><tr><td>超大只追加表按时间范围查</td><td>BRIN</td></tr><tr><td>只有少部分行会被查</td><td>部分索引</td></tr></tbody></table><ul><li>GIN 查得快、写入代价高</li><li><code>LIKE &#39;%xx%&#39;</code> 可用 GIN + <code>pg_trgm</code> 扩展</li></ul><p><strong>常见坑</strong>：生产建索引用 <code>CREATE INDEX CONCURRENTLY</code>，失败会留下无效索引，要手动删掉重建。</p>`,5),o(`p`,null,[l[83]||=i(`→ 详见 `,-1),s(m,{to:`/database/2_postgresql/3_topic_index.html#%E4%B9%9D%E3%80%81%E5%A6%82%E4%BD%95%E9%80%89%E6%8B%A9`},{default:r(()=>[...l[82]||=[i(`PostgreSQL 索引类型`,-1)]]),_:1})]),l[167]||=e(`<h3 id="q35-pg-的流复制和逻辑复制有什么区别-synchronous-commit-和复制槽要注意什么" tabindex="-1"><a class="header-anchor" href="#q35-pg-的流复制和逻辑复制有什么区别-synchronous-commit-和复制槽要注意什么"><span>Q35：PG 的流复制和逻辑复制有什么区别？<code>synchronous_commit</code> 和复制槽要注意什么？</span></a></h3><p><strong>一句话</strong>：PG 只有一种日志 WAL，既管崩溃恢复也管复制，没有 binlog。流复制把 WAL 原样传过去，备库和主库一模一样、只读，用于高可用；逻辑复制把 WAL 解析成行变更，可以只同步部分表、跨大版本，用于升级、数据分发和 CDC。</p><ul><li><code>synchronous_commit</code>：控制提交时等到哪一步，从「不等本地落盘」到「等备库重放完」分好几档，默认 <code>on</code> 是等同步备库落盘</li><li>只有配置了同步备库才会等；只配一个同步备库时，它挂了主库的提交会全部卡住</li><li>复制槽会为消费者保留 WAL，消费者一直不来，WAL 就一直堆到磁盘写满；用 <code>max_slot_wal_keep_size</code> 设上限</li><li>逻辑复制不同步 DDL 和序列的当前值</li><li>故障切换要靠外部工具，主流是 Patroni</li></ul>`,3),o(`p`,null,[l[85]||=i(`→ 详见 `,-1),s(m,{to:`/database/2_postgresql/5_topic_replication.html#%E4%BA%8C%E3%80%81wal-%E4%B8%8E%E6%B5%81%E5%A4%8D%E5%88%B6`},{default:r(()=>[...l[84]||=[i(`PostgreSQL 复制与高可用`,-1)]]),_:1})]),l[168]||=e(`<h2 id="八、分布式数据库与分库分表" tabindex="-1"><a class="header-anchor" href="#八、分布式数据库与分库分表"><span>八、分布式数据库与分库分表</span></a></h2><h3 id="q36-什么时候需要分库分表-分片键如何选择" tabindex="-1"><a class="header-anchor" href="#q36-什么时候需要分库分表-分片键如何选择"><span>Q36：什么时候需要分库分表？分片键如何选择？</span></a></h3><p><strong>一句话</strong>：分库分表是最后一招。先优化索引和 SQL、加缓存、读写分离、归档冷数据，单库的容量、写入量或连接数确实扛不住了再拆。分片键选最常用的查询条件里分布均匀、不会修改的字段，比如 user_id。</p><ul><li>垂直拆分：按业务拆成不同的库</li><li>水平拆分：按分片键把一张表的行分散到多个库表</li><li>分片键选得好，大部分查询只落到一个分片</li><li>不按分片键的查询：用映射表、冗余表或搜索引擎</li></ul>`,4),o(`p`,null,[l[88]||=i(`→ 详见 `,-1),s(m,{to:`/interview/13_high_con.html#q24-%E4%BB%80%E4%B9%88%E6%97%B6%E5%80%99%E9%9C%80%E8%A6%81%E5%88%86%E5%BA%93%E5%88%86%E8%A1%A8-%E5%88%86%E7%89%87%E9%94%AE%E5%A6%82%E4%BD%95%E9%80%89%E6%8B%A9`},{default:r(()=>[...l[86]||=[i(`高并发面试题解答`,-1)]]),_:1}),l[89]||=i(`、`,-1),s(m,{to:`/high-con/5_data_scaling.html#%E5%9B%9B%E3%80%81%E5%88%86%E5%BA%93%E5%88%86%E8%A1%A8`},{default:r(()=>[...l[87]||=[i(`数据层扩展`,-1)]]),_:1})]),l[169]||=e(`<h3 id="q37-shardingsphere-jdbc-和-proxy-有什么区别-跨分片查询和事务如何处理" tabindex="-1"><a class="header-anchor" href="#q37-shardingsphere-jdbc-和-proxy-有什么区别-跨分片查询和事务如何处理"><span>Q37：ShardingSphere-JDBC 和 Proxy 有什么区别？跨分片查询和事务如何处理？</span></a></h3><p><strong>一句话</strong>：JDBC 版是应用里的一个 jar，当作数据库驱动用，没有额外网络开销，只支持 Java；Proxy 版是独立部署的数据库代理，任何语言都能连，方便统一管理，但多一跳网络、要自己做高可用。常见做法是应用用 JDBC 版，DBA 用 Proxy 版。</p><table><thead><tr><th>对比</th><th>JDBC</th><th>Proxy</th></tr></thead><tbody><tr><td>形态</td><td>应用内 jar</td><td>独立服务</td></tr><tr><td>语言</td><td>只支持 Java</td><td>任意</td></tr><tr><td>性能</td><td>无额外网络开销</td><td>多一跳</td></tr></tbody></table><ul><li>跨分片查询：SQL 改写后发给各分片并行执行，再合并结果；不带分片键就要查所有分片</li><li>跨分片分页：<code>LIMIT 100, 10</code> 会变成每个分片都查 <code>LIMIT 0, 110</code>，深分页要改成游标分页</li><li>事务：支持本地事务、XA 和柔性事务（Seata），只管同一个 ShardingSphere 实例里的数据源</li></ul>`,4),o(`p`,null,[l[91]||=i(`→ 详见 `,-1),s(m,{to:`/database/5_practice/2_sharding.html#%E4%BA%8C%E3%80%81%E4%B8%A4%E7%A7%8D%E6%8E%A5%E5%85%A5%E5%BD%A2%E6%80%81`},{default:r(()=>[...l[90]||=[i(`分库分表与中间件`,-1)]]),_:1})]),l[170]||=e(`<h3 id="q38-分库分表如何不停机迁移-以后扩容怎么做" tabindex="-1"><a class="header-anchor" href="#q38-分库分表如何不停机迁移-以后扩容怎么做"><span>Q38：分库分表如何不停机迁移？以后扩容怎么做？</span></a></h3><p><strong>一句话</strong>：迁移按「双写 → 历史数据迁移 → 校验对账 → 灰度切读 → 停旧写」五步走，每一步都能回退；扩容的关键是一开始就预分配足够多的逻辑分片，以后只搬整个库，不重新哈希每一行。</p><ul><li>双写优先用 CDC 订阅旧库 binlog（数据库变更日志）写新库，而不是业务代码写两遍；先记下 binlog 位点再拷全量，拷贝期间的修改不会丢</li><li>校验：按主键区间比较行数和 checksum，不一致的段再逐行比对，差异以旧库为准修复</li><li>切换：读按用户哈希灰度放量；最后短暂停写，等增量追平再切写，并开启新库到旧库的反向同步，方便回滚</li><li>预分配：比如 32 库 × 32 表 = 1024 张逻辑表，初期 4 台实例每台放 8 个库，扩容只改数据源地址，路由规则不变</li><li>没有预分配时按倍数扩（N → 2N），每个旧分片只迁一半；4 → 5 这种非倍数扩容要搬 80% 的数据</li></ul><p><strong>常见坑</strong>：库和表都用 <code>h % 32</code> 路由，库下标永远等于表下标，每个库只有 1 张表有数据；表下标应取 <code>(h / 32) % 32</code>。</p>`,4),o(`p`,null,[l[94]||=i(`→ 详见 `,-1),s(m,{to:`/database/5_practice/2_sharding.html#%E5%85%AB%E3%80%81%E5%B9%B3%E6%BB%91%E8%BF%81%E7%A7%BB%E4%B8%8E%E6%89%A9%E5%AE%B9`},{default:r(()=>[...l[92]||=[i(`分库分表与中间件`,-1)]]),_:1}),l[95]||=i(`、`,-1),s(m,{to:`/high-con/5_data_scaling.html`},{default:r(()=>[...l[93]||=[i(`数据层扩展`,-1)]]),_:1})]),l[171]||=e(`<h3 id="q39-tidb-的数据如何分片与复制-事务和-mysql-有什么不同" tabindex="-1"><a class="header-anchor" href="#q39-tidb-的数据如何分片与复制-事务和-mysql-有什么不同"><span>Q39：TiDB 的数据如何分片与复制？事务和 MySQL 有什么不同？</span></a></h3><p><strong>一句话</strong>：TiDB 分三层：TiDB Server 负责计算 SQL，TiKV 负责存数据，PD 负责调度。数据按主键范围切成一个个 Region（默认 256 MiB），每个 Region 有多个副本用 Raft 协议保持一致，PD 负责拆分和搬迁 Region。</p><ul><li>隔离级别：RR 实际是快照隔离，没有间隙锁；靠 <code>FOR UPDATE</code> 锁范围防插入的写法要改成唯一约束</li><li>自增 ID：唯一但不连续；写入热点用 <code>AUTO_RANDOM</code></li><li>不支持存储过程、触发器、自定义函数</li><li>大事务有大小限制，批量写入要分批提交</li></ul><p><strong>常见坑</strong>：单调递增的主键会让写入都集中到最后一个 Region，形成热点。</p>`,4),o(`p`,null,[l[97]||=i(`→ 详见 `,-1),s(m,{to:`/database/3_relational/1_distributed_db.html#%E4%B8%80%E3%80%81tidb`},{default:r(()=>[...l[96]||=[i(`分布式数据库`,-1)]]),_:1})]),l[172]||=e(`<h3 id="q40-分库分表和分布式数据库怎么选-tidb、oceanbase、aurora-polardb-有什么区别" tabindex="-1"><a class="header-anchor" href="#q40-分库分表和分布式数据库怎么选-tidb、oceanbase、aurora-polardb-有什么区别"><span>Q40：分库分表和分布式数据库怎么选？TiDB、OceanBase、Aurora / PolarDB 有什么区别？</span></a></h3><p><strong>一句话</strong>：分库分表复用成熟的 MySQL，成本低，但跨分片 JOIN、事务、扩容都要业务和中间件自己扛；分布式数据库把这些做进了数据库内部，对业务透明，代价是新的运维体系和更多资源。分片键清楚、查询模式稳定就分库分表；要跨分片强一致事务或透明扩容就选分布式数据库。</p><table><thead><tr><th>对比</th><th>TiDB</th><th>OceanBase</th><th>Aurora / PolarDB</th></tr></thead><tbody><tr><td>架构</td><td>多节点各存一部分</td><td>多节点各存一部分</td><td>计算和存储分离，共享存储</td></tr><tr><td>兼容</td><td>MySQL</td><td>MySQL；企业版兼容 Oracle</td><td>MySQL / PostgreSQL</td></tr><tr><td>写扩展</td><td>加节点</td><td>加节点</td><td>一般只有一个写节点</td></tr><tr><td>典型场景</td><td>MySQL 扩容、HTAP</td><td>金融核心、Oracle 迁移</td><td>读多写少、从 RDS 升级</td></tr></tbody></table><p><strong>常见坑</strong>：单表千万级、单库扛得住时，先优化索引、归档和加缓存，不急着上分库分表或分布式数据库。</p>`,4),o(`p`,null,[l[100]||=i(`→ 详见 `,-1),s(m,{to:`/database/3_relational/1_distributed_db.html#%E4%B8%89%E3%80%81tidb-%E4%B8%8E-oceanbase-%E9%80%89%E5%9E%8B%E5%AF%B9%E6%AF%94`},{default:r(()=>[...l[98]||=[i(`分布式数据库`,-1)]]),_:1}),l[101]||=i(`、`,-1),s(m,{to:`/database/5_practice/2_sharding.html#%E4%B9%9D%E3%80%81%E9%80%89%E5%9E%8B%E5%BB%BA%E8%AE%AE`},{default:r(()=>[...l[99]||=[i(`分库分表与中间件`,-1)]]),_:1})]),l[173]||=e(`<h2 id="九、nosql-与选型" tabindex="-1"><a class="header-anchor" href="#九、nosql-与选型"><span>九、NoSQL 与选型</span></a></h2><h3 id="q41-mongodb-如何建模-多文档事务有哪些限制" tabindex="-1"><a class="header-anchor" href="#q41-mongodb-如何建模-多文档事务有哪些限制"><span>Q41：MongoDB 如何建模？多文档事务有哪些限制？</span></a></h3><p><strong>一句话</strong>：一起读的数据就放一起：一对一、一对少量且一起读写的子数据直接内嵌（订单和订单项），一对大量、多对多或要单独访问的用引用（用户和订单）。单个文档的写入本身是原子的，能内嵌就能避开多文档事务。</p><ul><li>单文档上限 16MB，会不断增长的数组（评论、日志）不要内嵌</li><li>多文档事务：默认要在 60 秒内完成，官方建议一次不超过 1000 个文档，冲突时要重试</li><li>写入默认要多数节点确认（<code>w: &quot;majority&quot;</code>）；从从节点读可能读到旧数据</li><li>分片键要覆盖主要查询条件；单调递增的键做范围分片会形成写热点</li></ul>`,4),o(`p`,null,[l[103]||=i(`→ 详见 `,-1),s(m,{to:`/database/4_nosql/2_document_db.html#%E4%BA%8C%E3%80%81%E6%96%87%E6%A1%A3%E5%BB%BA%E6%A8%A1`},{default:r(()=>[...l[102]||=[i(`文档数据库`,-1)]]),_:1})]),l[174]||=e(`<h3 id="q42-elasticsearch-为什么能快速全文检索-写入后为什么不能立刻搜到" tabindex="-1"><a class="header-anchor" href="#q42-elasticsearch-为什么能快速全文检索-写入后为什么不能立刻搜到"><span>Q42：Elasticsearch 为什么能快速全文检索？写入后为什么不能立刻搜到？</span></a></h3><p><strong>一句话</strong>：ES 用的是倒排索引，就像书后面的索引页：从「词」直接查到「包含它的文档列表」，不用逐篇扫描。写入的数据先在内存里，要等 refresh（默认每 1 秒一次）生成新的段文件后才能被搜到，所以叫「近实时」。</p><ul><li>写入先进内存缓冲，同时写 Translog（事务日志）保证不丢</li><li>refresh：生成新段、可以被搜到；flush：把段真正写到磁盘并清空 Translog</li><li>后台会合并小段，删除的文档在合并时才真正清除</li><li>中文分词：默认分词器把中文切成单字，要用 IK 等中文分词插件</li></ul><p><strong>常见坑</strong>：主分片数建好后不能直接改，规划时要留余量。</p>`,4),o(`p`,null,[l[106]||=i(`→ 详见 `,-1),s(m,{to:`/database/4_nosql/3_search_db.html#_3%E3%80%81%E5%80%92%E6%8E%92%E7%B4%A2%E5%BC%95`},{default:r(()=>[...l[104]||=[i(`搜索数据库`,-1)]]),_:1}),l[107]||=i(`、`,-1),s(m,{to:`/database/4_nosql/3_search_db.html#_1%E3%80%81%E5%86%99%E5%85%A5%E9%93%BE%E8%B7%AF`},{default:r(()=>[...l[105]||=[i(`搜索数据库`,-1)]]),_:1})]),l[175]||=e(`<h3 id="q43-es-深分页怎么做-数据如何从数据库同步到-es" tabindex="-1"><a class="header-anchor" href="#q43-es-深分页怎么做-数据如何从数据库同步到-es"><span>Q43：ES 深分页怎么做？数据如何从数据库同步到 ES？</span></a></h3><p><strong>一句话</strong>：<code>from + size</code> 默认最多翻到第 10000 条，越往后越慢；翻页用 <code>search_after</code> 配合 PIT（固定一个时间点的视图），<code>scroll</code> 只用于离线导出。同步数据时以数据库为准，通过 CDC 或消息队列捕获变更，再写入 ES。</p><ul><li><code>search_after</code>：带上上一页最后一条的排序值往后查，和游标翻页一个思路</li><li>同步：Outbox、MQ 或 CDC 捕获变更，组装成完整文档写入 ES</li><li>消息可能乱序或重复：用版本号或更新时间，旧版本不覆盖新版本</li><li>全量重建：建新索引，导完后用别名一次切过去</li></ul><p><strong>常见坑</strong>：在业务代码里同时写数据库和 ES（双写），一边失败就不一致，优先用 CDC 或可靠消息。</p>`,4),o(`p`,null,[l[110]||=i(`→ 详见 `,-1),s(m,{to:`/database/4_nosql/3_search_db.html#_3%E3%80%81%E6%B7%B1%E5%88%86%E9%A1%B5`},{default:r(()=>[...l[108]||=[i(`搜索数据库`,-1)]]),_:1}),l[111]||=i(`、`,-1),s(m,{to:`/database/4_nosql/3_search_db.html#%E5%85%AD%E3%80%81%E6%95%B0%E6%8D%AE%E5%90%8C%E6%AD%A5`},{default:r(()=>[...l[109]||=[i(`搜索数据库`,-1)]]),_:1})]),l[176]||=e(`<h3 id="q44-hbase、clickhouse、doris-starrocks-有什么区别-clickhouse-为什么不适合频繁更新" tabindex="-1"><a class="header-anchor" href="#q44-hbase、clickhouse、doris-starrocks-有什么区别-clickhouse-为什么不适合频繁更新"><span>Q44：HBase、ClickHouse、Doris / StarRocks 有什么区别？ClickHouse 为什么不适合频繁更新？</span></a></h3><p><strong>一句话</strong>：HBase 是按行键排序的超大 KV 存储，擅长海量数据按 key 随机读写；ClickHouse、Doris、StarRocks 是列式分析数据库，每列单独存、压缩率高，擅长大范围统计。ClickHouse 每次写入都生成一个不可修改的数据块，改和删只能打标记或重写整块，所以不适合频繁更新。</p><table><thead><tr><th>对比</th><th>擅长</th></tr></thead><tbody><tr><td>HBase</td><td>海量数据按 key 读写</td></tr><tr><td>ClickHouse</td><td>单张大宽表的分析，速度最快</td></tr><tr><td>Doris / StarRocks</td><td>多表 JOIN、实时更新、兼容 MySQL 协议</td></tr></tbody></table><ul><li>ClickHouse 写入要攒批：每次至少 1000 行，最好 1 万～10 万行</li><li>HBase 的行键单调递增会形成写热点，用哈希前缀或加盐打散</li></ul>`,4),o(`p`,null,[l[113]||=i(`→ 详见 `,-1),s(m,{to:`/database/4_nosql/0_column_db.html#%E5%9B%9B%E3%80%81%E9%80%89%E5%9E%8B%E5%AF%B9%E6%AF%94`},{default:r(()=>[...l[112]||=[i(`列式与 OLAP 数据库`,-1)]]),_:1})]),l[177]||=e(`<h3 id="q45-时序数据为什么不用-mysql-存-什么时候需要图数据库" tabindex="-1"><a class="header-anchor" href="#q45-时序数据为什么不用-mysql-存-什么时候需要图数据库"><span>Q45：时序数据为什么不用 MySQL 存？什么时候需要图数据库？</span></a></h3><p><strong>一句话</strong>：时序数据写得多、按时间追加、按时间段统计、过期按时间整批删。MySQL 扛不住这么高频的写入，按时间删数据要 DELETE 海量行，压缩也差；时序数据库在这些方面都专门做了优化。图数据库适合查多层关系，比如「朋友的朋友的朋友」，关系型数据库每多一层就多一次 JOIN。</p><table><thead><tr><th>场景</th><th>推荐</th></tr></thead><tbody><tr><td>系统监控告警</td><td>Prometheus</td></tr><tr><td>已经在用 PostgreSQL</td><td>TimescaleDB</td></tr><tr><td>工业 IoT、设备采集</td><td>TDengine、IoTDB</td></tr><tr><td>社交关系、风控团伙</td><td>Neo4j、NebulaGraph</td></tr></tbody></table><ul><li>关系只有一两层时，用 SQL 的递归查询就够了，不必上图数据库</li></ul><p><strong>常见坑</strong>：时序数据库里把 user_id、订单号这种取值很多的字段当标签，序列数会爆炸。</p>`,5),o(`p`,null,[l[116]||=i(`→ 详见 `,-1),s(m,{to:`/database/4_nosql/1_time_series_db.html#%E5%85%AD%E3%80%81%E9%80%89%E5%9E%8B%E5%AF%B9%E6%AF%94`},{default:r(()=>[...l[114]||=[i(`时序数据库`,-1)]]),_:1}),l[117]||=i(`、`,-1),s(m,{to:`/database/4_nosql/4_graph_db.html#%E4%BA%94%E3%80%81%E9%80%89%E5%9E%8B%E5%AF%B9%E6%AF%94`},{default:r(()=>[...l[115]||=[i(`图数据库`,-1)]]),_:1})]),l[178]||=e(`<h2 id="十、连接池、cdc-与备份" tabindex="-1"><a class="header-anchor" href="#十、连接池、cdc-与备份"><span>十、连接池、CDC 与备份</span></a></h2><h3 id="q46-连接池大小怎么设-maxlifetime、keepalivetime-与-wait-timeout-是什么关系" tabindex="-1"><a class="header-anchor" href="#q46-连接池大小怎么设-maxlifetime、keepalivetime-与-wait-timeout-是什么关系"><span>Q46：连接池大小怎么设？<code>maxLifetime</code>、<code>keepaliveTime</code> 与 <code>wait_timeout</code> 是什么关系？</span></a></h3><p><strong>一句话</strong>：连接池不是越大越好。经验公式「数据库 CPU 核数 × 2 + 磁盘数」算的是数据库那边总共需要的活跃连接数，要分给所有应用实例。<code>maxLifetime</code> 要比数据库和防火墙的空闲超时都短，否则池里会留着已经被断开的连接。</p><ul><li>例子：数据库 16 核 SSD，总共约 33 个连接，4 个应用实例每个配 8～10 个就够</li><li>所有实例的连接池加起来（包括扩容后）不要超过数据库 <code>max_connections</code> 的约 80%</li><li><code>keepaliveTime</code> 要小于所有空闲超时中最短的那个，定期探活</li><li>池被用光时：先查慢 SQL 和长事务，再看是否连接泄漏（<code>leakDetectionThreshold</code> 可以定位）</li></ul><p><strong>常见坑</strong>：报 Communications link failure，多半是连接被数据库或防火墙断了，池里还在用。</p>`,5),o(`p`,null,[l[120]||=i(`→ 详见 `,-1),s(m,{to:`/database/5_practice/3_connection_pool.html#_4%E3%80%81%E6%B1%A0%E5%A4%A7%E5%B0%8F%E4%BC%B0%E7%AE%97`},{default:r(()=>[...l[118]||=[i(`数据库连接池`,-1)]]),_:1}),l[121]||=i(`、`,-1),s(m,{to:`/interview/13_high_con.html#q37-%E6%95%B0%E6%8D%AE%E5%BA%93%E8%BF%9E%E6%8E%A5%E6%B1%A0%E6%98%AF%E4%B8%8D%E6%98%AF%E8%B6%8A%E5%A4%A7%E8%B6%8A%E5%A5%BD-%E6%B0%B4%E5%B9%B3%E6%89%A9%E5%AE%B9%E6%97%B6%E8%A6%81%E6%B3%A8%E6%84%8F%E4%BB%80%E4%B9%88`},{default:r(()=>[...l[119]||=[i(`高并发面试题解答`,-1)]]),_:1})]),l[179]||=e(`<h3 id="q47-postgresql-为什么需要-pgbouncer-transaction-模式有什么限制" tabindex="-1"><a class="header-anchor" href="#q47-postgresql-为什么需要-pgbouncer-transaction-模式有什么限制"><span>Q47：PostgreSQL 为什么需要 PgBouncer？transaction 模式有什么限制？</span></a></h3><p><strong>一句话</strong>：PG 每个连接是一个进程，开销大，一般只能开几百个连接，微服务实例一多就不够用。PgBouncer 把大量客户端连接复用到少量真实连接上；生产常用 transaction 模式，事务结束就归还连接，代价是不能用会话级的状态。</p><table><thead><tr><th>模式</th><th>什么时候归还真实连接</th><th>限制</th></tr></thead><tbody><tr><td><code>session</code>（默认）</td><td>客户端断开时</td><td>没限制，但复用率低</td></tr><tr><td><code>transaction</code></td><td>事务结束时</td><td>不能用会话级 <code>SET</code>、<code>LISTEN</code>、跨事务的临时表等</td></tr><tr><td><code>statement</code></td><td>每条语句结束时</td><td>不能用多语句事务</td></tr></tbody></table><ul><li>会话级 <code>SET</code> 改用 <code>SET LOCAL</code>（只在当前事务内生效）</li><li>应用里仍保留 HikariCP 控制并发，PgBouncer 负责收拢到数据库的真实连接</li></ul><p><strong>常见坑</strong>：JDBC 预编译语句在旧版 PgBouncer 下会出错，要升级到 1.21 以上，或在 JDBC URL 加 <code>prepareThreshold=0</code>。</p>`,5),o(`p`,null,[l[123]||=i(`→ 详见 `,-1),s(m,{to:`/database/5_practice/3_connection_pool.html#%E4%BA%94%E3%80%81pgbouncer`},{default:r(()=>[...l[122]||=[i(`数据库连接池`,-1)]]),_:1})]),l[180]||=e(`<h3 id="q48-基于-binlog-的-cdc-原理是什么-canal、debezium、flink-cdc-怎么选" tabindex="-1"><a class="header-anchor" href="#q48-基于-binlog-的-cdc-原理是什么-canal、debezium、flink-cdc-怎么选"><span>Q48：基于 binlog 的 CDC 原理是什么？Canal、Debezium、Flink CDC 怎么选？</span></a></h3><p><strong>一句话</strong>：CDC 工具把自己伪装成一个从库，从 MySQL 拉取 binlog，解析出每行改前改后的数据，转成事件发给下游。前提是 binlog 为 ROW 格式、账号有复制权限、<code>server_id</code> 不和别的从库重复。</p><table><thead><tr><th>工具</th><th>形态</th><th>适合</th></tr></thead><tbody><tr><td>Canal</td><td>独立服务，可投递到 MQ</td><td>已有 Canal 体系、只同步 MySQL</td></tr><tr><td>Debezium</td><td>Kafka Connect 连接器</td><td>已有 Kafka、多种数据库、Outbox</td></tr><tr><td>Flink CDC</td><td>Flink 数据源</td><td>实时计算、整库入仓入湖</td></tr></tbody></table><ul><li>消息至少投递一次，可能重复，下游必须幂等（按主键 upsert 或按版本号去重）</li><li>按主键分区，保证同一行的变更按顺序处理</li><li>binlog 保留时间要比 CDC 可能停机的时间长</li></ul><p><strong>常见坑</strong>：<code>server_id</code> 重复时两个客户端会互相把对方踢下线、反复重连。</p>`,5),o(`p`,null,[l[126]||=i(`→ 详见 `,-1),s(m,{to:`/database/5_practice/0_cdc_tools.html#%E4%B8%80%E3%80%81%E5%B7%A5%E5%85%B7%E5%AF%B9%E6%AF%94`},{default:r(()=>[...l[124]||=[i(`CDC 工具`,-1)]]),_:1}),l[127]||=i(`、`,-1),s(m,{to:`/flink/6_cdc.html`},{default:r(()=>[...l[125]||=[i(`Flink CDC`,-1)]]),_:1})]),l[181]||=e(`<h3 id="q49-如何设计-mysql-postgresql-的备份与时间点恢复-pitr" tabindex="-1"><a class="header-anchor" href="#q49-如何设计-mysql-postgresql-的备份与时间点恢复-pitr"><span>Q49：如何设计 MySQL / PostgreSQL 的备份与时间点恢复（PITR）？</span></a></h3><p><strong>一句话</strong>：备份方案由两个目标决定：最多能丢多少数据（RPO）、最多多久恢复（RTO）。基本做法是「定期全量备份 + 持续归档日志」：全量提供起点，再用 binlog / WAL 把数据补到任意时间点。没做过恢复演练的备份等于没有备份。</p><table><thead><tr><th>对比</th><th>MySQL</th><th>PostgreSQL</th></tr></thead><tbody><tr><td>逻辑备份</td><td><code>mysqldump --single-transaction</code></td><td><code>pg_dump</code></td></tr><tr><td>物理备份</td><td>XtraBackup、CLONE 插件</td><td><code>pg_basebackup</code></td></tr><tr><td>日志归档</td><td>持续保存 binlog</td><td><code>archive_command</code> 归档 WAL</td></tr><tr><td>恢复到时间点</td><td>全量恢复后用 <code>mysqlbinlog</code> 重放到指定时间</td><td>设置 <code>recovery_target_time</code> 恢复</td></tr></tbody></table><ul><li>大库用物理备份，恢复快；逻辑备份用于跨版本迁移、单表恢复</li><li>3-2-1 原则：3 份副本、2 种介质、1 份异地</li></ul><p><strong>常见坑</strong>：PG 做时间点恢复时忘了创建 <code>recovery.signal</code> 文件，数据库会正常启动并忽略所有恢复参数。</p>`,5),o(`p`,null,[l[129]||=i(`→ 详见 `,-1),s(m,{to:`/database/5_practice/1_backup_recovery.html`},{default:r(()=>[...l[128]||=[i(`数据备份与恢复`,-1)]]),_:1})])])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};